Rewrite the following GNU C++14 code into exactly 5 different variants. The code reads and writes I/O from the console. Each variant should have the exact same functionality as the given code, meaning that it should have the same output for any given input. Make the variants meaningfully different from one another and from the original code, while preserving functionality exactly.
Print all 5 rewritten variants, numbered from 1 to 5. Do not stop early, do not skip an index, and do not repeat an index. Use this exact format:
<perturbed_code_1>
<your_rewritten_code_1>
</perturbed_code_1>
<perturbed_code_2>
<your_rewritten_code_2>
</perturbed_code_2>
<perturbed_code_3>
<your_rewritten_code_3>
</perturbed_code_3>
<perturbed_code_4>
<your_rewritten_code_4>
</perturbed_code_4>
<perturbed_code_5>
<your_rewritten_code_5>
</perturbed_code_5>
Each block must contain one complete program. Do not provide any other text or markdown fences.

Here is the original GNU C++14 code you have to rewrite:
<original_code>
#include<iostream>
#include<cstdio>
#include<vector>
#include<algorithm>
#define ll long long
#define R register
using namespace std;
const int mod1=998244353,mod2=1e9+7;
inline ll read(){
	ll a=0,b=1;
	char s=getchar();
	while(s<48||s>57){
		if(s=='-') b=-1;
		s=getchar();
	}
	while(s>=48&&s<=57)
		a=(a<<1)+(a<<3)+s-48,s=getchar();
	return a*b;
}
ll n;
ll cnt1,sum[10];
vector<int> v[10];
void dfs1(int len,int val){
	if(len>6) return;
	v[len].push_back((cnt1-val+mod1)%mod1);
	sum[len]+=(cnt1-val+mod1)%mod1;
	++cnt1;
	for(R int i=0;i<=9;i=-~i) dfs1(len+1,val*10+i);
}
ll cnt2,ans;
inline bool check(ll x){return x*1000000+999999<=n&&x*10000000>n;}
int pw[7]={1,10,100,1000,10000,100000,1000000};
void dfs2(int len,ll val){
	if(val>n) return;
	if(check(val)){
		for(R int i=0;i<=6;i=-~i){
			ll v1=((cnt2+1-val*pw[i])%mod1+mod1)%mod1;
			int num=lower_bound(v[i].begin(),v[i].end(),mod1-v1)-v[i].begin();
			ans=(ans+(sum[i]+v[i].size()*v1-1LL*mod1*(v[i].size()-num)))%mod2;
		}
		cnt2+=cnt1;
	}
	else{
		if(len) ++cnt2;
		ans=(ans+((cnt2-val)%mod1+mod1)%mod1)%mod2;
		for(R int i=(!len);i<=9;i=-~i) dfs2(len+1,val*10+i);
	}
}
int main(){
	n=read();
	dfs1(0,0);
	for(R int i=0;i<=6;i=-~i) sort(v[i].begin(),v[i].end());
	dfs2(0,0);
	printf("%lld\n",ans);
	return 0;
}

</original_code>
